34	const sumBy = <T>(values: T[], amount: (value: T) => number): number =>
35	  values.reduce((total, value) => total + amount(value), 0);
36	
37	const PROCESSING_FEE = 5;
38	
39	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
40	
41	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
42	  sword: 100,
43	  amulet: 60,
44	  staff: 80,
45	  potion: 40,
46	  rune: 25,
47	  moonstone: 25,
48	};
49	
50	const itemBasePremium = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];
51	
52	const BLOCK_SIZE = 3;
53	
54	const BLOCK_BASE_PREMIUM = 60;
55	
56	const basePremiumForSameTypeItems = (items: Item[]): number =>
57	  items.length === BLOCK_SIZE
58	    ? BLOCK_BASE_PREMIUM
59	    : sumBy(items, itemBasePremium);
60	
61	const sameTypeGroups = (items: Item[]): Item[][] => {
62	  const groupsByType = new Map<string, Item[]>();
63	  for (const item of items) {
64	    const group = groupsByType.get(item.type) ?? [];
65	    group.push(item);
66	    groupsByType.set(item.type, group);
67	  }
68	  return [...groupsByType.values()];
69	};
70	
71	const CURSE_SURCHARGE_RATE = 0.5;
72	
73	const itemSurcharge = (item: Item): number =>
74	  item.cursed === true ? itemBasePremium(item) * CURSE_SURCHARGE_RATE : 0;
75	
76	const quotePremium = (step: QuoteStep): number => {
77	  const policyBasePremium = sumBy(
78	    sameTypeGroups(step.items),
79	    basePremiumForSameTypeItems,
80	  );
81	  const itemSurcharges = sumBy(step.items, itemSurcharge);
82	  const firstInsuranceSurcharge =
83	    policyBasePremium * FIRST_INSURANCE_SURCHARGE_RATE;
84	  return (
85	    policyBasePremium +
86	    itemSurcharges +
87	    firstInsuranceSurcharge +
88	    PROCESSING_FEE
89	  );
90	};
91	
92	export const runScenario = (scenario: Scenario): ScenarioResult => ({
93	  results: scenario.steps.map((step) => ({ premium: quotePremium(step) })),
94	});
